function numDecodings(s) {
  if (!s || s[0] === '0') return 0;
  const n = s.length;
  const dp = new Array(n + 1).fill(0);
  dp[0] = 1;
  dp[1] = 1;
  for (let i = 2; i <= n; i++) {
    const oneDigit = Number(s[i - 1]);
    const twoDigits = Number(s.slice(i - 2, i));
    if (oneDigit >= 1 && oneDigit <= 9) {
      dp[i] += dp[i - 1];
    }
    if (twoDigits >= 10 && twoDigits <= 26) {
      dp[i] += dp[i - 2];
    }
  }
  return dp[n];
}

function numDecodings(s) {
  if (!s || s[0] === '0') return 0;
  let prev2 = 1;
  let prev1 = 1;
  for (let i = 2; i <= s.length; i++) {
    let current = 0;
    const oneDigit = Number(s[i - 1]);
    const twoDigits = Number(s.slice(i - 2, i));
    if (oneDigit >= 1 && oneDigit <= 9) {
      current += prev1;
    }
    if (twoDigits >= 10 && twoDigits <= 26) {
      current += prev2;
    }
    prev2 = prev1;
    prev1 = current;
  }
  return prev1;
}

def numDecodings(s: str) -> int:
    if not s or s[0] == "0":
        return 0
    n = len(s)
    dp = [0] * (n + 1)
    dp[0] = 1
    dp[1] = 1
    for i in range(2, n + 1):
        one_digit = int(s[i - 1])
        two_digits = int(s[i - 2 : i])
        if 1 <= one_digit <= 9:
            dp[i] += dp[i - 1]
        if 10 <= two_digits <= 26:
            dp[i] += dp[i - 2]
    return dp[n]

